    // -------------------------------------------------------------------------
    // Animation
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();
    const statusElement = document.getElementById("status");
    const progressElement = document.getElementById("progress");
    const stepElements = [
      document.getElementById("step-0"),
      document.getElementById("step-1"),
      document.getElementById("step-2")
    ];

    const ladderStartTimes = [0.15, 3.15, 6.15];
    const ladderDuration = 2.8;
    const ladderHold = 1.15;
    const doorStart = 8.45;
    const doorDuration = 3.1;

    const openDoorAngle = -1.48;
    const closedDoorAngle = 0;
    const ropeLength = 4.15;

    function easeOutCubic(t) {
      return 1 - Math.pow(1 - t, 3);
    }

    function updateLadders(elapsed) {
      ladders.forEach((ladder, index) => {
        const time = elapsed - ladderStartTimes[index];
        let angle;

        if (time < 0) {
          angle = -1.48;
        } else if (time < ladderDuration) {
          angle = THREE.MathUtils.lerp(
            -1.48,
            -0.035,
            easeOutCubic(time / ladderDuration)
          );
        } else {
          angle = -0.035;
        }

        ladder.rotation.z = angle;
      });
    }

    function updateDoor(elapsed) {
      const time = elapsed - doorStart;
      let rotation;

      if (time < 0) {
        rotation = openDoorAngle;
      } else if (time < doorDuration) {
        rotation = THREE.MathUtils.lerp(
          openDoorAngle,
          closedDoorAngle,
          easeOutCubic(time / doorDuration)
        );
      } else {
        rotation = closedDoorAngle;
      }

      doorPivot.rotation.y = rotation;
      doorPivot.updateMatrixWorld(true);

      // Counterweight rope is attached to the upper corner of the moving door.
      const attachment = doorPivot.localToWorld(
        new THREE.Vector3(doorWidth, 1.1, 0)
      );

      const ropeDistance = attachment.distanceTo(pulleyPosition);
      const verticalRopeLength = ropeLength - ropeDistance;
      const weightY = pulleyPosition.y - verticalRopeLength;

      counterweight.position.y = weightY;

      positionRope(
        ropeToPulley,
        attachment,
        pulleyPosition
      );

      positionRope(
        ropeToWeight,
        pulleyPosition,
        new THREE.Vector3(
          pulleyPosition.x,
          weightY + 0.43,
          pulleyPosition.z
        )
      );
    }

    function updateInterface(elapsed) {
      let status;
      let progress = 0;

      if (elapsed < 0.15) {
        status = "Preparing settlement";
      } else if (elapsed < 3.15) {
        status = "Raising ladder I";
        stepElements[0].classList.add("active");
      } else if (elapsed < 6.15) {
        status = "Raising ladder II";
        stepElements[0].classList.add("complete");
        stepElements[1].classList.add("active");
      } else if (elapsed < 8.45) {
        status = "Raising ladder III";
        stepElements[0].classList.add("complete");
        stepElements[1].classList.add("complete");
        stepElements[2].classList.add("active");
      } else if (elapsed < doorStart + doorDuration) {
        status = "Counterweight door sealing";
        stepElements[0].classList.add("complete");
        stepElements[1].classList.add("complete");
        stepElements[2].classList.add("complete");
      } else {
        status = "Settlement secured";
        stepElements[0].classList.add("complete");
        stepElements[1].classList.add("complete");
        stepElements[2].classList.add("complete");
      }

      statusElement.textContent = status;
      progressElement.style.width = `${Math.min(100, (elapsed / 11.6) * 100)}%`;
    }

    function animate() {
      requestAnimationFrame(animate);

      const delta = Math.min(clock.getDelta(), 0.05);
      const elapsed = clock.elapsedTime;

      updateLadders(elapsed);
      updateDoor(elapsed);
      updateInterface(elapsed);

      // Gentle, restrained flicker for the warm settlement lights.
      fireLight.intensity = 12 + Math.sin(elapsed * 8.3) * 0.7;
      doorwayLight.intensity = 4.4 + Math.sin(elapsed * 6.1) * 0.25;

      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
